    log.emit("instance_exit_confirmed","\"name\":\"target\",\"pid\":"+std::to_string(child.pid)+",\"created\":"+std::to_string(child.creation)+",\"forced\":"+std::string(graceful?"false":"true"));
    JOBOBJECT_BASIC_ACCOUNTING_INFORMATION accounting{};const auto job_end=GetTickCount64()+1000;do{check(QueryInformationJobObject(job.value,JobObjectBasicAccountingInformation,&accounting,sizeof(accounting),nullptr),"QueryInformationJobObject.probe");if(!accounting.ActiveProcesses)break;Sleep(1);}while(GetTickCount64()<job_end);
